description:
Implement `promiseAllSettled(promises)` that resolves with an array of outcome objects — never rejects. Each object has `status: 'fulfilled'` + `value`, or `status: 'rejected'` + `reason`.

**Example:**
```js
const results = await promiseAllSettled([
  Promise.resolve(1),
  Promise.reject('oops'),
]);
// [{ status: 'fulfilled', value: 1 }, { status: 'rejected', reason: 'oops' }]
```

starter_code:
export function promiseAllSettled(promises) {
  // your code here
}

test_suite:
test('fulfilled promises have status and value', async () => {
  const results = await promiseAllSettled([Promise.resolve(42)]);
  expect(results[0]).toEqual({ status: 'fulfilled', value: 42 });
});

test('rejected promises have status and reason', async () => {
  const results = await promiseAllSettled([Promise.reject('err')]);
  expect(results[0]).toEqual({ status: 'rejected', reason: 'err' });
});

test('never rejects even if all reject', async () => {
  await expect(promiseAllSettled([Promise.reject('a'), Promise.reject('b')])).resolves.toBeDefined();
});

test('order matches input', async () => {
  const results = await promiseAllSettled([Promise.resolve(1), Promise.reject(2), Promise.resolve(3)]);
  expect(results.map(r => r.status)).toEqual(['fulfilled', 'rejected', 'fulfilled']);
});

// __hidden__
test('empty array resolves to empty array', async () => {
  const results = await promiseAllSettled([]);
  expect(results).toEqual([]);
});

solution:
export function promiseAllSettled(promises) {
  return Promise.all(
    promises.map(p =>
      Promise.resolve(p)
        .then(value => ({ status: 'fulfilled', value }))
        .catch(reason => ({ status: 'rejected', reason }))
    )
  );
}
